from django.shortcuts import render
from django.http import HttpResponse
from register.models import *
from transaction.utils import *
from django.contrib.auth.models import User

def index(request):
	if 'user_id' in request.session:
		nxtgnuser=User.objects.get(id=request.session.get('user_id')).first_name
	else:
		nxtgnuser=False
	k={}
	for i in Register.objects.all():
		k[i.k_id]=[", ".join([i.lastname, i.firstname]), Level(i.k_id)]
	k=dict(sorted(k.items(), key=lambda item: item[1]))
	return render(request, 'kids/index.html', {'k':k, 'nxtgnuser':nxtgnuser}, content_type='text/html')

def ltst(request):
	if 'user_id' in request.session:
		nxtgnuser=User.objects.get(id=request.session.get('user_id')).first_name
	else:
		nxtgnuser=False
	k={}
	for i in Register.objects.all():
		k[i.k_id]=[i.registered_date, ", ".join([i.lastname, i.firstname]), Level(i.k_id)]
	k=dict(sorted(k.items(), key=lambda item: item[1], reverse=True))
	return render(request, 'kids/ltst.html', {'k':k, 'nxtgnuser':nxtgnuser}, content_type='text/html')	

